def _cle_dans_fichier(chemin):
    try:
        contenu = open(chemin, encoding="utf-8-sig").read()
    except Exception:
        return None
    for ligne in contenu.splitlines():
        l = ligne.strip()
        if l.startswith("sk-"):
            return l
    t = contenu.strip()
    if t.startswith("sk-"):
        return t
    return None


def _chercher_cle_ailleurs():
    """Si la cle n'est pas ici, on la recupere dans une ancienne installation de Luciana."""
    racines = [os.path.join(HOME, d) for d in ("Desktop", "Downloads", "Documents")]
    vus = 0
    for racine in racines:
        if not os.path.isdir(racine):
            continue
        prof0 = racine.count(os.sep)
        for base, dirs, noms in os.walk(racine):
            if base.count(os.sep) - prof0 > 3:
                dirs[:] = []
                continue
            vus += 1
            if vus > 3000:  # on ne cherche pas indefiniment, pour rester rapide
                return None
            if "cle_api.txt" in noms:
                cle = _cle_dans_fichier(os.path.join(base, "cle_api.txt"))
                if cle:
                    return cle
    return None


def lire_cle():
    cle = _cle_dans_fichier(FICHIER_CLE)
    if cle:
        return cle
    cle = _chercher_cle_ailleurs()
    if cle:
        try:
            with open(FICHIER_CLE, "w", encoding="utf-8") as f:
                f.write(cle)
        except Exception:
            pass
        return cle
    return None


