def _archiver_note(chemin, quoi):
    """Garde l'etat ACTUEL du fichier dans anciennes_notes/<quoi>/<quoi>_AAAA-MM-JJ_HHhMM-SS.json,
    AVANT qu'il soit remplace. Rend le chemin garde, ou '' si rien n'a pu etre garde."""
    try:
        if not os.path.exists(chemin):
            return ""
        with open(chemin, "r", encoding="utf-8") as f:
            contenu = f.read()
        json.loads(contenu)                     # on n'archive jamais un fichier abime
        dest = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi)
        os.makedirs(dest, exist_ok=True)
        p = os.path.join(dest, "%s_%s.json" % (quoi, time.strftime("%Y-%m-%d_%Hh%M-%S")))
        if os.path.exists(p):                   # deux ecritures dans la meme seconde
            p = p[:-5] + "-2.json"
        with open(p, "w", encoding="utf-8") as f:
            f.write(contenu)
        gardes = sorted(x for x in os.listdir(dest) if x.endswith(".json"))
        for vieux in gardes[:-ANCIENNES_NOTES_GARDEES]:
            try:
                os.remove(os.path.join(dest, vieux))
            except OSError:
                pass
        return p
    except Exception:
        return ""


def _versions_anciennes(quoi):
    """La liste des anciennes versions gardees, de la plus recente a la plus ancienne."""
    dest = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi)
    try:
        return sorted((x for x in os.listdir(dest) if x.endswith(".json")), reverse=True)
    except Exception:
        return []


def _charger_version_ancienne(quoi, nom):
    chemin = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi, nom)
    try:
        with open(chemin, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _quand_version(nom):
    """'carnet_2026-09-30_18h04-12.json' -> '2026-09-30 18h04'."""
    m = re.search(r"(\d{4}-\d{2}-\d{2})_(\d{2})h(\d{2})", nom or "")
    return "%s %sh%s" % (m.group(1), m.group(2), m.group(3)) if m else (nom or "?")


def sauvegarde_du_jour():
    """Une copie par jour de la memoire, des souvenirs, du carnet et des comptes, dans
    ~/Luciana/sauvegardes/AAAA-MM-JJ/. On garde les 60 derniers jours."""
    try:
        jour = time.strftime("%Y-%m-%d")
        dest = os.path.join(DOSSIER_SAUVEGARDES, jour)
        os.makedirs(dest, exist_ok=True)
        for nom in _FICHIERS_A_SAUVEGARDER:
            src = os.path.join(DOSSIER, nom)
            if os.path.exists(src) and not os.path.exists(os.path.join(dest, nom)):
                try:
                    with open(src, "r", encoding="utf-8") as f:
                        json.load(f)  # on ne sauvegarde pas un fichier abime par-dessus un bon
                    shutil.copy2(src, os.path.join(dest, nom))
                except Exception:
                    pass
        jours = sorted(d for d in os.listdir(DOSSIER_SAUVEGARDES) if os.path.isdir(os.path.join(DOSSIER_SAUVEGARDES, d)))
        for vieux in jours[:-60]:
            shutil.rmtree(os.path.join(DOSSIER_SAUVEGARDES, vieux), ignore_errors=True)
    except Exception:
        pass


def charger_memoire():
    return _charger_json_sur(FICHIER_MEMOIRE, [])


def sauver_memoire(messages):
    # Ecriture sure : on ecrit d'abord un fichier temporaire, puis on le renomme.
    # Comme ca, meme une coupure de courant ne peut pas abimer la memoire.
    # (Aucun plafond : on garde TOUT l'historique, on ne perd jamais rien.)
    _garder_precedent(FICHIER_MEMOIRE)
    tmp = FICHIER_MEMOIRE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(messages, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, FICHIER_MEMOIRE)


def ajouter_a_la_memoire(message_utilisateur, texte_reponse, actions=None, note_lignes=None):
    """Ajoute l'echange (toi + elle) a la memoire, de facon SURE meme si le PC et le
    telephone parlent en meme temps : on relit la memoire fraiche et on ajoute a la fin.
    On note aussi la date et les outils VRAIMENT utilises (avec leur resultat reel), pour
    qu'elle sache au message suivant ce qu'elle a fait pour de vrai (pas juste ce qu'elle a dit)."""
    date = time.strftime("%Y-%m-%d %H:%M")
    sauvegarde_du_jour()
    with _verrou_memoire:
        frais = charger_memoire()
        moi = {"role": "user", "content": message_utilisateur, "date": date}
        if note_lignes:
            moi["note_lignes"] = list(note_lignes)   # v88 : mises a jour du carnet/souvenirs, chacune EN ENTIER
        frais.append(moi)
        rep = {"role": "assistant", "content": texte_reponse, "date": date}
        if actions:
            rep["actions"] = actions
        frais.append(rep)
        sauver_memoire(frais)


def ajouter_note_memoire(texte):
    """Ajoute une note de Luciana dans la memoire (ex : le rapport d'un chantier Claude Code fini),
    pour qu'elle le retrouve au message suivant au lieu de l'oublier."""
    with _verrou_memoire:
        frais = charger_memoire()
        frais.append({"role": "assistant", "content": texte, "date": time.strftime("%Y-%m-%d %H:%M")})
        sauver_memoire(frais)


# ---------- FENETRE "LA JOURNEE ENTIERE" + RAPPEL AUTOMATIQUE ----------
VEILLE_GARDEE = 20              # messages d'avant aujourd'hui gardes sous les yeux (fin de la veille)
BUDGET_FENETRE = 200000         # garde-fou (~60 000 tokens) pour une journee enorme (documents colles)
PAQUET_FENETRE = 50             # si le garde-fou joue, la fenetre avance par gros paquets (rarement)


PAUSE_NOUVELLE_JOURNEE = 5 * 3600   # une "journee de travail" commence apres une pause de 5 h ou plus QUI CONTIENT LA NUIT


def _heure_msg(m):
    try:
        return time.mktime(time.strptime(str(m.get("date"))[:16], "%Y-%m-%d %H:%M"))
    except Exception:
        return None


def _pause_de_nuit(avant, apres):
    """Vrai si entre ces deux moments il y a une vraie nuit : au moins 5 h, et 4 h du matin dedans."""
    if apres - avant < PAUSE_NOUVELLE_JOURNEE:
        return False
    t = time.localtime(avant)
    quatre = time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 4, 0, 0, 0, 0, -1))
    if quatre <= avant:
        quatre += 24 * 3600
    return quatre <= apres


def _debut_journee(hist):
    """Index du 1er message de la journee de travail en cours : celui qui suit la derniere NUIT de pause.
    Travailler apres minuit ne coupe plus la journee (avant, a minuit, elle 'oubliait' la soiree), et une
    longue pause dans la journee (ex. 10 h -> 17 h) ne la coupe pas non plus."""
    suivant = time.time()
    for i in range(len(hist) - 1, -1, -1):
        t = _heure_msg(hist[i])
        if t is None:
            if i == len(hist) - 1:
                continue            # le message qu'on vient de recevoir (pas encore date)
            return i + 1
        if _pause_de_nuit(t, suivant):
            return i + 1
        suivant = min(suivant, t)
    return 0


def _debut_fenetre(hist):
    """Premier message envoye au cerveau : toute la journee de TRAVAIL (v62 : elle ne se coupe plus a minuit)
    + la fin de la precedente. Garde-fou de taille (cout) EXACTEMENT comme en v61 : si la fenetre depasse
    200 000 car., le debut avance par paquets de 50 messages (rarement : chaque saut = cache a reecrire).
    v63 : l'abrege des vieux gros messages (v62) est retire : il faisait reecrire le cache bien plus souvent."""
    debut = max(0, _debut_journee(hist) - VEILLE_GARDEE)
    tailles = [len(m.get("content") if isinstance(m.get("content"), str) else str(m.get("content"))) for m in hist]
    while sum(tailles[debut:]) > BUDGET_FENETRE and debut + PAQUET_FENETRE < len(hist):
        debut += PAQUET_FENETRE
    return debut



_MOTS_VIDES = set("""alors aussi autre avant avec avoir bien bon bonne cela celle celui cest cette comme comment dans
depuis donc elle elles encore entre etait etre faire fait faut fois font hein ici juste leur leurs lui mais meme
merci mieux moins mon mes notre nous parce pas peut plus pour pourquoi quand quel quelle quelque quoi sais sans
sera ses sont sous suis sur tant tes tien tiens tjrs toi ton tous tout toute toutes tres trop une vais veux vos
votre vous voila voilà ouais oui non euh bah ben bref chose choses truc trucs faire dire dit peux pouvez pourrais
luciana fred aujourd demain hier matin soir maintenant jamais toujours""".split())


def _mots_cles(texte):
    mots = []
    for m in re.findall(r"[A-Za-zÀ-ÿ0-9']{4,}", texte or ""):
        m = _sans_accents(m.strip("'"))
        if m not in _MOTS_VIDES and m not in mots:
            mots.append(m)
    return mots[:12]


def rappel_automatique(message, hist, debut):
    """Cherche SOI-MEME dans les archives (conversations d'avant la fenetre + resultats d'outils) les
    passages lies au message de Fred, pour que Luciana les ait sous les yeux sans avoir a y penser."""
    mots = _mots_cles(message)
    if not mots:
        return ""
    seuil = 1 if len(mots) == 1 else 2
    trouves = []  # (score, ordre, texte)
    for i in range(debut - 1, -1, -1):
        c = hist[i].get("content")
        if not isinstance(c, str) or not c.strip():
            continue
        t = _sans_accents(c)
        score = sum(1 for m in mots if m in t)
        if score >= seuil:
            qui = "Fred" if hist[i].get("role") == "user" else "toi"
            pos = min((t.find(m) for m in mots if m in t), default=0)
            extrait = c[max(0, pos - 200): pos + 500].strip()
            trouves.append((score, -i, "[%s, %s] %s" % (hist[i].get("date", "date inconnue"), qui, extrait)))
    try:
        with open(FICHIER_ARCHIVE_OUTILS, "r", encoding="utf-8") as f:
            lignes = f.readlines()
    except Exception:
        lignes = []
    for j, ligne in enumerate(lignes):
        try:
            a = json.loads(ligne)
        except Exception:
            continue
        res = a.get("resultat", "")
        t = _sans_accents("%s %s" % (a.get("entree", ""), res))
        score = sum(1 for m in mots if m in t)
        if score >= seuil:
            pos = max(0, min((_sans_accents(res).find(m) for m in mots if m in _sans_accents(res)), default=0))
            trouves.append((score, -(len(hist) + j), "[%s, resultat de ton outil %s] %s" % (
                a.get("date", "?"), a.get("outil", "?"), res[max(0, pos - 200): pos + 500].strip())))
    if not trouves:
        return ""
    trouves.sort(key=lambda x: (-x[0], x[1]))
    morceaux, total = [], 0
    for _, _, t in trouves[:3]:
        if total + len(t) > 3000:
            break
        morceaux.append(t); total += len(t)
    return ("[Rappel automatique de ta memoire (ecrit par le programme) : passages ANCIENS lies a ce message. "
            "Sers-t'en si c'est utile, cherche plus avec chercher_dans_memoire si besoin]\n" + "\n---\n".join(morceaux))


# ---------- CARNET DE CHANTIER (ou elle en est sur chaque projet en cours) ----------
FICHIER_CARNET = os.path.join(DOSSIER, "carnet.json")


def charger_carnet():
    d = _charger_json_sur(FICHIER_CARNET, {})
    return d if isinstance(d, dict) else {}


def _sauver_carnet(d):
    _garder_precedent(FICHIER_CARNET)
    _archiver_note(FICHIER_CARNET, "carnet")   # v76 : l'ancienne version est gardee en entier, datee
    tmp = FICHIER_CARNET + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, FICHIER_CARNET)


_verrou_notes = threading.RLock()   # PC + telephone : souvenirs/carnet lus-modifies-ecrits un a la fois


def _sous_verrou_notes(f):
    def g(e):
        with _verrou_notes:
            return f(e)
    g.__name__ = f.__name__
    return g


@_sous_verrou_notes
def outil_carnet(e):
    nom =(e.get("projet") or "").strip()
    etat = (e.get("etat") or "").strip()
    clore = bool(e.get("clore"))
    if not nom:
        return "Dis-moi le nom du projet (ex: Legere Plume)."
    carnet = charger_carnet()
    cle = next((k for k in carnet if k.lower() == nom.lower()), nom)
    if clore:
        if cle in carnet:
            del carnet[cle]
            _sauver_carnet(carnet)
            return "Carnet du projet '%s' ferme (projet termine)." % cle
        return "Je n'ai pas de carnet ouvert pour '%s'." % nom
    if not etat:
        return "Dis-moi ou on en est sur ce projet (but, fait, reste a faire)."
    carnet[cle] = {"etat": etat[:20000], "maj": time.strftime("%Y-%m-%d %H:%M")}
    _sauver_carnet(carnet)
    return ("Carnet du projet '%s' mis a jour pour de vrai. (L'ancienne version entiere est gardee, "
            "datee : si un detail a saute, relis-la avec l'outil 'anciennes_notes'.)" % cle)


@_sous_verrou_notes
def outil_anciennes_notes(e):
    """v76 : RELIRE une ancienne version du carnet de chantier ou des souvenirs. Avant, remplacer
    le carnet effacait pour toujours ce qui n'avait pas ete recopie ; maintenant chaque version est
    gardee, datee, et tu peux revenir la lire."""
    quoi = _sans_accents(str(e.get("quoi") or "carnet")).strip()
    quoi = "souvenirs" if quoi.startswith("souv") else "carnet"
    action = _sans_accents(str(e.get("action") or "lister")).strip()
    versions = _versions_anciennes(quoi)
    if not versions:
        return ("Je n'ai encore aucune ancienne version de %s en archive (elles se gardent a chaque "
                "modification, a partir de la v76)." % quoi)
    if action.startswith("list"):
        apercu = ", ".join(_quand_version(v) for v in versions[:25])
        return ("%d ancienne(s) version(s) de %s gardee(s), de la plus recente a la plus ancienne : %s%s.\n"
                "Pour en relire une : action 'relire' avec 'quand' (ex : %s)." % (
                    len(versions), quoi, apercu, " ..." if len(versions) > 25 else "",
                    _quand_version(versions[0])))
    if not action.startswith("relire") and not action.startswith("lire") and not action.startswith("ouvrir"):
        return "Action inconnue '%s'. Actions : lister, relire." % action
    quand = _sans_accents(str(e.get("quand") or "")).strip()
    choisie = versions[0]
    if quand:
        jour = _lire_date(quand)
        candidates = [v for v in versions if quand.replace(" ", "") in _sans_accents(v).replace(" ", "")]
        if not candidates and jour:
            candidates = [v for v in versions if jour in v]
        if not candidates:
            return ("Je n'ai pas de version de %s qui corresponde a '%s'. Celles que j'ai : %s." % (
                quoi, e.get("quand"), ", ".join(_quand_version(v) for v in versions[:20])))
        choisie = candidates[0]
    contenu = _charger_version_ancienne(quoi, choisie)
    if contenu is None:
        return "Je n'ai pas pu relire le fichier %s (il est peut-etre abime). Essaie une autre version." % choisie
    titre = "VERSION DU %s (%s), relue telle quelle" % (_quand_version(choisie), quoi)
    if quoi == "souvenirs":
        liste = contenu if isinstance(contenu, list) else []
        actuels = charger_souvenirs()
        disparus = [s for s in liste if s not in actuels]
        texte = "\n".join("- " + str(s) for s in liste[:400]) or "(vide)"
        if disparus:
            texte += ("\n\nCE QUI N'EST PLUS DANS TES SOUVENIRS D'AUJOURD'HUI (%d) :\n" % len(disparus) +
                      "\n".join("- " + str(s) for s in disparus[:60]))
        return "%s :\n%s" % (titre, texte)
    carnet = contenu if isinstance(contenu, dict) else {}
    projet = (e.get("projet") or "").strip()
    if projet:
        cle = next((k for k in carnet if projet.lower() in k.lower()), "")
        if not cle:
            return ("Cette version du carnet ne parle pas de '%s'. Projets dedans : %s." % (
                projet, ", ".join(carnet) or "aucun"))
        v = carnet[cle]
        return "%s — projet %s (mis a jour le %s) :\n%s" % (titre, cle, v.get("maj", "?"), v.get("etat", ""))
    if not carnet:
        return "%s : le carnet etait vide a ce moment-la." % titre
    blocs = ["- %s (mis a jour le %s) :\n%s" % (nom, v.get("maj", "?"), str(v.get("etat", ""))[:6000])
             for nom, v in carnet.items()]
    return "%s — %d projet(s) :\n%s" % (titre, len(carnet), "\n\n".join(blocs))


# ---------- v67 : RECETTES (elle APPREND : la facon de faire une tache reussie, reutilisee ensuite) ----------
FICHIER_RECETTES = os.path.join(DOSSIER, "recettes.json")


def charger_recettes():
    d = _charger_json_sur(FICHIER_RECETTES, {})
    return d if isinstance(d, dict) else {}


def _sauver_recettes(d):
    _garder_precedent(FICHIER_RECETTES)
    tmp = FICHIER_RECETTES + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, FICHIER_RECETTES)


def _index_recettes(rec):
    """Ce qu'elle a sous les yeux : le nom et QUAND s'en servir (les etapes, elle les ouvre avec 'voir')."""
    return {nom: v.get("quand", "") for nom, v in (rec or {}).items()}


@_sous_verrou_notes
def outil_recettes(e):
    action = (e.get("action") or "lister").strip().lower()
    rec = charger_recettes()
    nom = (e.get("nom") or "").strip()
    cle = next((k for k in rec if k.lower() == nom.lower()), nom)
    if action == "lister":
        if not rec:
            return "Tu n'as encore aucune recette."
        return "Tes recettes :\n" + "\n".join("- %s : %s" % (k, v.get("quand", "")) for k, v in rec.items())
    if not nom:
        return "Donne le nom de la recette."
    if action == "voir":
        if cle not in rec:
            return "Pas de recette '%s'. Tes recettes : %s." % (nom, ", ".join(rec) or "aucune")
        r = rec[cle]
        r["utilisee"] = int(r.get("utilisee", 0)) + 1
        _sauver_recettes(rec)
        return "RECETTE '%s' (quand : %s ; mise a jour le %s) :\n%s" % (cle, r.get("quand", ""), r.get("maj", "?"), r.get("etapes", ""))
    if action == "enregistrer":
        etapes = (e.get("etapes") or "").strip()
        if not etapes:
            return "Donne les etapes : ce que tu as fait, dans l'ordre, avec les outils et les reglages qui ont marche."
        ancien = rec.get(cle, {})
        rec[cle] = {"quand": (e.get("quand") or ancien.get("quand") or "").strip(), "etapes": etapes,
                    "maj": time.strftime("%Y-%m-%d %H:%M"), "utilisee": ancien.get("utilisee", 0)}
        _sauver_recettes(rec)
        return "Recette '%s' %s pour de vrai." % (cle, "mise a jour" if ancien else "enregistree")
    if action == "oublier":
        if cle not in rec:
            return "Pas de recette '%s'." % nom
        del rec[cle]
        _sauver_recettes(rec)
        return "Recette '%s' oubliee (Fred l'a demande)." % cle
    return "Action inconnue '%s'. Actions : lister, voir, enregistrer, oublier." % action


def _texte_carnet(carnet=None):
    carnet = charger_carnet() if carnet is None else carnet
    if not carnet:
        return ""
    lignes = ["TON CARNET DE CHANTIER (les projets en cours, a jour ; tu repars TOUJOURS de la) :"]
    for nom, v in carnet.items():
        lignes.append("- %s (mis a jour le %s) : %s" % (nom, v.get("maj", "?"), v.get("etat", "")))
    return "\n".join(lignes)


# ---------- ARCHIVE DES OUTILS (tout ce que ses outils ont renvoye, en entier, sur le disque) ----------
FICHIER_ARCHIVE_OUTILS = os.path.join(DOSSIER, "archive_outils.jsonl")
_verrou_archive = threading.Lock()


def archiver_outil(nom, entree, sortie):
    """Garde le resultat COMPLET de chaque outil (un mail lu, un rapport, une liste...) pour
    qu'elle puisse le retrouver plus tard avec chercher_dans_memoire. Rien de ce qu'elle a vu ne se perd."""
    try:
        if isinstance(sortie, dict):
            resultat = str(sortie.get("texte") or "(image ou document montre au cerveau)")
        else:
            resultat = str(sortie)
        try:
            ent = json.dumps(entree or {}, ensure_ascii=False)
        except Exception:
            ent = str(entree)
        ligne = json.dumps({"date": time.strftime("%Y-%m-%d %H:%M"), "outil": nom,
                            "entree": ent[:5000], "resultat": resultat[:100000]}, ensure_ascii=False)
        with _verrou_archive:
            with open(FICHIER_ARCHIVE_OUTILS, "a", encoding="utf-8") as f:
                f.write(ligne + "\n")
    except Exception:
        pass


# ---------- ETAT DU MATIN : souvenirs et carnet qui ne cassent plus le cache ----------
# Les souvenirs et le carnet sont dans la partie "cachee" du debut. Les changer en cours de journee
# faisait repayer tout le cache (~0,20-0,40 $ sur Opus a chaque fois). Maintenant : on prend une
# photo le matin (partie cachee, stable toute la journee) et les changements du jour sont ajoutes a
# la fin du dernier message (partie non cachee). Le lendemain, tout est regroupe. Rien n'est perdu.
FICHIER_ETAT_MATIN = os.path.join(DOSSIER, "etat_du_matin.json")


def etat_du_matin():
    jour = time.strftime("%Y-%m-%d")
    etat = _charger_json_sur(FICHIER_ETAT_MATIN, {})
    if not isinstance(etat, dict) or etat.get("date") != jour:
        etat = {"date": jour, "souvenirs": charger_souvenirs(), "carnet": charger_carnet(),
                "recettes": _index_recettes(charger_recettes())}
        try:
            tmp = FICHIER_ETAT_MATIN + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(etat, f, ensure_ascii=False, indent=1)
            os.replace(tmp, FICHIER_ETAT_MATIN)
        except Exception:
            pass
    return etat


ENTETE_NOUVEAUTES = ("[Mises a jour de ta memoire faites AUJOURD'HUI (ecrit par le programme) : elles comptent "
                     "plus que ce qui est ecrit plus haut]")


def nouveautes_memoire(etat):
    """Ce qui a change dans les souvenirs et le carnet depuis la photo du matin."""
    lignes = lignes_nouveautes(etat)
    if not lignes:
        return ""
    return ENTETE_NOUVEAUTES + "\n" + "\n".join(lignes)


def lignes_nouveautes(etat):
    """v87 : les lignes de nouveautes_memoire, une par changement."""
    lignes = []
    matin_s = etat.get("souvenirs") or []
    actuels = charger_souvenirs()
    for x in actuels:
        if x not in matin_s:
            lignes.append("- Nouveau souvenir : %s" % x)
    for x in matin_s:
        if x not in actuels:
            lignes.append("- Souvenir retire ou corrige (ne plus s'en servir) : %s" % x)
    matin_c = etat.get("carnet") or {}
    carnet = charger_carnet()
    for nom, v in carnet.items():
        if matin_c.get(nom) != v:
            lignes.append("- Carnet, projet %s (mis a jour le %s) : %s" % (nom, v.get("maj", "?"), v.get("etat", "")))
    for nom in matin_c:
        if nom not in carnet:
            lignes.append("- Carnet : projet %s ferme (termine)." % nom)
    matin_r = etat.get("recettes") or {}
    recettes = _index_recettes(charger_recettes())
    for nom, quand in recettes.items():
        if matin_r.get(nom) != quand:
            lignes.append("- Nouvelle recette : %s (quand : %s)" % (nom, quand))
    for nom in matin_r:
        if nom not in recettes:
            lignes.append("- Recette oubliee (ne plus s'en servir) : %s" % nom)
    return lignes


def _lignes_deja_notees(hist, debut):
    """v88 : ce qui est DEJA dans la fenetre. Une 'ligne' de nouveaute peut tenir sur PLUSIEURS lignes de texte
    (un projet du carnet entier) : on garde donc chaque nouveaute en entier (champ 'note_lignes'), jamais coupee
    aux retours a la ligne. BUG DE LA v87 (vu par Luciana chez Fred le 02/10) : les notes etaient recoupees ligne
    par ligne, un projet de plusieurs lignes n'etait donc JAMAIS reconnu, et TOUT le carnet etait renote a chaque
    message (la conversation grossissait de dizaines de milliers de caracteres a chaque fois)."""
    deja, anciennes = set(), []
    for m in hist[debut:]:
        if isinstance(m.get("note_lignes"), list):
            deja.update(str(x) for x in m["note_lignes"])
        elif m.get("note_memoire"):
            anciennes.append(str(m["note_memoire"]))     # notes ecrites par la v87 (texte d'un seul bloc)
    return deja, "\n" + "\n".join(anciennes) + "\n"


def nouveautes_a_noter(etat, hist, debut):
    """v87/v88 : les mises a jour du jour (carnet, souvenirs, recettes) qui ne sont pas encore dans la fenetre.
    Chacune est ecrite UNE fois, au message ou elle apparait, puis relue depuis le cache."""
    lignes = lignes_nouveautes(etat)
    if not lignes:
        return []
    deja, anciennes = _lignes_deja_notees(hist, debut)
    return [l for l in lignes if l not in deja and ("\n" + l + "\n") not in anciennes]


def note_nouveautes_a_ecrire(etat, hist, debut):
    neuves = nouveautes_a_noter(etat, hist, debut)
    return (ENTETE_NOUVEAUTES + "\n" + "\n".join(neuves)) if neuves else ""


def _note_a_montrer(m, vus, textes_vus):
    """v88 : la note d'un message telle qu'elle part au cerveau. Une nouveaute deja montree plus haut dans la fenetre
    n'est pas remontree (repare aussi les copies en double ecrites par la v87). Ne depend QUE des messages d'avant :
    le debut de la conversation reste identique d'un message a l'autre (cache intact)."""
    if isinstance(m.get("note_lignes"), list):
        a_montrer = [str(x) for x in m["note_lignes"] if str(x) not in vus]
        vus.update(a_montrer)
        return (ENTETE_NOUVEAUTES + "\n" + "\n".join(a_montrer)) if a_montrer else ""
    t = str(m.get("note_memoire") or "")
    if not t or t in textes_vus:
        return ""
    textes_vus.add(t)
    return t


def _sans_accents(t):
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFD", t.lower()) if unicodedata.category(c) != "Mn")


# =====================================================================
#  v76 : LA FOUILLE DE MEMOIRE (le vrai correctif du 01/10/2026)
#  CE QUI N'ALLAIT PAS (constate, pas devine) : l'outil ne rendait que les 8 passages LES PLUS
#  RECENTS, il n'y avait AUCUNE recherche par date ni par periode, et les messages DU JOUR
#  noyaient tous les passages anciens. Fred a demande 5 fois un echange de la veille sans
#  l'obtenir, et un prix (2500 lei, le PC plus cher CHOISI PAR la cliente Daniela) a ete confondu
#  avec le prix de reference du business.
#  CE QUI CHANGE : recherche par DATE et par PERIODE, tri au choix, jusqu'a 50 resultats,
#  REPARTITION par journee (les jours ANCIENS passent devant), mots APPROCHANTS si rien d'exact,
#  ouverture de TOUTE la conversation d'une journee, et les resultats d'outils + le journal de
#  bord sont fouilles comme les dialogues. Aucune limite a 24 h, aucun blocage.
#  On ne touche PAS au stockage : la memoire n'est ni effacee ni deplacee, seule la fouille change.
# =====================================================================
_JOUR_ISO = re.compile(r"(\d{4})-(\d{2})-(\d{2})")


def _jour_de(horodatage):
    """La journee 'AAAA-MM-JJ' d'une date de la memoire, ou '' si on ne sait pas."""
    m = _JOUR_ISO.search(str(horodatage or ""))
    return m.group(0) if m else ""


def _lire_date(x):
    """Accepte 'AAAA-MM-JJ', '01/10/2026', '1-10-26'... et rend 'AAAA-MM-JJ' (ou '' si illisible)."""
    t = str(x or "").strip()
    if not t:
        return ""
    m = _JOUR_ISO.search(t)
    if m:
        return m.group(0)
    m = re.search(r"\b(\d{1,2})[/.\- ](\d{1,2})[/.\- ](\d{2,4})\b", t)
    if m:
        j, mo, a = m.groups()
        a = a if len(a) == 4 else ("20" + a)
        try:
            return "%s-%02d-%02d" % (a, int(mo), int(j))
        except ValueError:
            return ""
    return ""


def _jour_decale(n):
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + n * 86400))


def _periode_en_dates(periode):
    """Traduit une periode dite comme on parle en (du, au). ('', '') si on ne comprend pas :
    dans ce cas on cherche partout, on ne bloque jamais."""
    p = _sans_accents(str(periode or "")).strip()
    if not p:
        return "", ""
    lundi = -time.localtime().tm_wday          # recul jusqu'au lundi de cette semaine
    if "avant-hier" in p or "avant hier" in p:
        return _jour_decale(-2), _jour_decale(-2)
    if "hier" in p:
        return _jour_decale(-1), _jour_decale(-1)
    if "aujourd" in p or p in ("ce jour", "today"):
        return _jour_decale(0), _jour_decale(0)
    if "semaine" in p:
        if "derniere" in p or "passee" in p or "avant" in p:
            return _jour_decale(lundi - 7), _jour_decale(lundi - 1)
        return _jour_decale(lundi), _jour_decale(0)
    if "mois" in p:
        t = time.localtime()
        if "dernier" in p or "passe" in p or "precedent" in p:
            a, mo = (t.tm_year - 1, 12) if t.tm_mon == 1 else (t.tm_year, t.tm_mon - 1)
            dernier = [31, 29 if (a % 4 == 0 and (a % 100 != 0 or a % 400 == 0)) else 28,
                       31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1]
            return "%04d-%02d-01" % (a, mo), "%04d-%02d-%02d" % (a, mo, dernier)
        return "%04d-%02d-01" % (t.tm_year, t.tm_mon), _jour_decale(0)
    if "annee" in p:
        t = time.localtime()
        if "derniere" in p or "passee" in p:
            return "%04d-01-01" % (t.tm_year - 1), "%04d-12-31" % (t.tm_year - 1)
        return "%04d-01-01" % t.tm_year, _jour_decale(0)
    for n, nom in ((3, "trois jours"), (7, "sept jours"), (15, "quinze jours"), (30, "trente jours")):
        if nom in p:
            return _jour_decale(-n), _jour_decale(0)
    m = re.search(r"(\d+)\s*(jour|semaine|mois)", p)
    if m:
        n = int(m.group(1)) * {"jour": 1, "semaine": 7, "mois": 30}[m.group(2)]
        return _jour_decale(-n), _jour_decale(0)
    d = _lire_date(periode)
    return (d, d) if d else ("", "")


def _mots_recherche(mots):
    return [m for m in (_sans_accents(x) for x in re.split(r"[\s,;/]+", str(mots or "")) if x.strip())
            if len(m) > 1]


def _variantes_mot(m):
    """Mots PROCHES du mot cherche : singulier/pluriel, et une racine courte (sans accents, deja fait).
    Grace a ca, 'prix' retrouve aussi 'prix', 'carnets' retrouve 'carnet', 'Daniela' retrouve 'Daniel'."""
    v = {m}
    if len(m) > 3 and m[-1] in "sx":
        v.add(m[:-1])
    else:
        v.add(m + "s")
    if len(m) > 5:
        v.add(m[:-2])          # racine : 'danie' retrouve Daniela, Daniel, Danielle
    return v


def _extrait_autour(texte, mots, avant=250, apres=700):
    """Le morceau du passage qui contient vraiment le mot cherche (pas le debut du message)."""
    t = _sans_accents(texte)
    pos = min((t.find(m) for m in mots if m in t), default=-1)
    if pos < 0:
        return texte[:avant + apres] + (" [...]" if len(texte) > avant + apres else "")
    debut = max(0, pos - avant)
    bout = texte[debut: pos + apres]
    return ("[...] " if debut else "") + bout.strip() + (" [...]" if pos + apres < len(texte) else "")


def _passages_memoire(avec_outils=True, avec_journal=True):
    """TOUT ce qui est garde sur le PC, ramene a un seul format :
    {"date", "jour", "qui", "texte"}. Trois sources, pas une seule :
      1) vos dialogues (luciana_memoire.json, garde depuis le premier jour) ;
      2) le resultat COMPLET de ses outils (mails lus, rapports de chantier, listes...) ;
      3) le journal de bord des journees (Documents\\Journal_Luciana)."""
    passages = []
    for m in charger_memoire():
        c = m.get("content")
        if not isinstance(c, str) or not c.strip():
            continue
        d = str(m.get("date") or "")
        passages.append({"date": d, "jour": _jour_de(d), "texte": c,
                         "qui": "Fred" if m.get("role") == "user" else "Toi (Luciana)"})
    if avec_outils:
        try:
            with open(FICHIER_ARCHIVE_OUTILS, "r", encoding="utf-8") as f:
                lignes = f.readlines()
        except Exception:
            lignes = []
        for ligne in lignes:
            try:
                a = json.loads(ligne)
            except Exception:
                continue
            d = str(a.get("date") or "")
            res = str(a.get("resultat") or "")
            if not res.strip():
                continue
            passages.append({"date": d, "jour": _jour_de(d), "texte": res,
                             "qui": "Resultat de ton outil %s (demande : %s)" % (
                                 a.get("outil", "?"), str(a.get("entree") or "")[:200])})
    if avec_journal:
        for jour, texte in _journal_tous_les_jours().items():
            passages.append({"date": jour, "jour": jour, "texte": texte,
                             "qui": "Journal de bord de la journee"})
    return passages


def _repartir_par_jour(trouves, combien):
    """LE correctif du 01/10 : les messages DU JOUR ne noient plus les passages anciens.
    On range les resultats par journee, puis on sert les journees les PLUS ANCIENNES d'abord,
    a tour de role : chaque jour garde sa place, et les jours anciens remontent."""
    par_jour = {}
    for t in trouves:
        par_jour.setdefault(t.get("jour") or "0000-00-00", []).append(t)
    for j in par_jour:
        par_jour[j].sort(key=lambda t: (-t["score"], t.get("date", "")))
    jours = sorted(par_jour)                      # du plus ancien au plus recent
    gardes, tour = [], 0
    while len(gardes) < combien and any(len(v) > tour for v in par_jour.values()):
        for j in jours:
            if len(gardes) >= combien:
                break
            if len(par_jour[j]) > tour:
                gardes.append(par_jour[j][tour])
        tour += 1
    return gardes


def _jours_en_archive(passages=None):
    passages = _passages_memoire() if passages is None else passages
    return sorted({p["jour"] for p in passages if p.get("jour")})


def conversation_du_jour(jour, maxi=60000):
    """Ouvre la conversation ENTIERE d'une journee : tous les messages, dans l'ordre, plus les
    resultats d'outils de ce jour-la et le journal de bord s'il existe."""
    jour = _lire_date(jour)
    if not jour:
        return "Donne-moi la journee a ouvrir, par exemple 2026-09-30 (ou dis 'hier')."
    passages = _passages_memoire()
    du_jour = [p for p in passages if p.get("jour") == jour]
    if not du_jour:
        dispo = _jours_en_archive(passages)
        proches = [j for j in dispo if j <= jour][-3:] + [j for j in dispo if j > jour][:3]
        return ("Je n'ai aucun message garde au %s. Les journees que j'ai en archive, autour : %s. "
                "(Au total %d journees, de %s a %s.)" % (
                    jour, ", ".join(proches) or "aucune", len(dispo),
                    dispo[0] if dispo else "?", dispo[-1] if dispo else "?"))
    du_jour.sort(key=lambda p: p.get("date", ""))
    morceaux, total = [], 0
    coupe = False
    for p in du_jour:
        bloc = "[%s] %s : %s" % (p.get("date") or jour, p["qui"], p["texte"])
        if total + len(bloc) > maxi:
            coupe = True
            break
        morceaux.append(bloc)
        total += len(bloc)
    entete = "CONVERSATION ENTIERE DU %s (%d passage(s) sur %d)" % (jour, len(morceaux), len(du_jour))
    if coupe:
        entete += " — journee tres longue, j'ai pris le debut ; demande une autre partie si besoin"
    return entete + " :\n\n" + "\n\n".join(morceaux)


def outil_chercher_memoire(e):
    """Fouille TOUTE la memoire gardee sur le PC : vos dialogues depuis le premier jour, le resultat
    complet de ses outils, et le journal de bord. Par mots, par date, par periode."""
    combien = int(e.get("combien") or 12)
    combien = max(1, min(combien, 50))
    tri = _sans_accents(str(e.get("tri") or "recent"))
    du, au = _lire_date(e.get("du")), _lire_date(e.get("au"))
    if not du and not au and e.get("periode"):
        du, au = _periode_en_dates(e.get("periode"))
    # Une journee entiere demandee : on ouvre la conversation complete, c'est tout.
    jour_voulu = e.get("jour") or e.get("journee")
    if jour_voulu:
        j = _lire_date(jour_voulu) or (_periode_en_dates(jour_voulu)[0])
        return conversation_du_jour(j or jour_voulu)
    mots = _mots_recherche(e.get("mots"))
    tous = _passages_memoire()          # lu UNE seule fois : la memoire peut etre enorme
    passages = tous
    if not passages:
        return "Je n'ai encore rien en archive sur ce PC (ni conversation, ni resultat d'outil)."
    if du or au:
        a, b = du or "0000-00-00", au or "9999-12-31"
        if a > b:
            a, b = b, a
        passages = [p for p in passages if p.get("jour") and a <= p["jour"] <= b]
        if not passages:
            dispo = _jours_en_archive(tous)
            return ("Je n'ai aucun passage garde entre %s et %s. Mes journees en archive vont du %s au %s "
                    "(%d journees). Dis-moi une autre periode, ou je cherche partout." % (
                        a, b, dispo[0] if dispo else "?", dispo[-1] if dispo else "?", len(dispo)))
    # Pas de mots-cles mais une periode : on rend la periode, du plus recent au plus ancien.
    if not mots:
        if not (du or au):
            dispo = _jours_en_archive(passages)
            return ("Dis-moi quels mots chercher, ou une periode ('hier', 'la semaine derniere', "
                    "du 2026-09-28 au 2026-09-30), ou une journee a ouvrir en entier ('jour'). "
                    "J'ai %d journees en archive, du %s au %s." % (
                        len(dispo), dispo[0] if dispo else "?", dispo[-1] if dispo else "?"))
        for p in passages:
            p["score"] = 1
        trouves, approche = passages, False
    else:
        exacts, partiels, approchants = [], [], []
        groupes = [_variantes_mot(m) for m in mots]
        for p in passages:
            t = _sans_accents(p["texte"])
            dedans = sum(1 for m in mots if m in t)
            if dedans == len(mots):
                p["score"] = 100 + dedans
                exacts.append(p)
            elif dedans:
                p["score"] = 50 + dedans
                partiels.append(p)
            else:
                proches = sum(1 for g in groupes if any(v in t for v in g))
                if proches:
                    p["score"] = 10 + proches
                    approchants.append(p)
        # D'abord les passages qui ont TOUS les mots ; s'il n'y en a pas assez, ceux qui en ont
        # une partie ; et en dernier recours les mots APPROCHANTS (pluriel, racine, accents).
        trouves = exacts
        approche = False
        if len(trouves) < combien:
            trouves = trouves + partiels
        if len(trouves) < combien and approchants:
            trouves = trouves + approchants
            approche = True
    if not trouves:
        dispo = _jours_en_archive(tous)
        return ("Rien trouve avec : %s%s. Ce que je peux faire tout de suite : chercher d'autres mots, "
                "ou ouvrir une journee entiere (j'ai %d journees en archive, du %s au %s)." % (
                    " ".join(mots) or "(aucun mot)",
                    " entre %s et %s" % (du or "le debut", au or "aujourd'hui") if (du or au) else "",
                    len(dispo), dispo[0] if dispo else "?", dispo[-1] if dispo else "?"))
    total_trouve = len(trouves)
    gardes = _repartir_par_jour(trouves, combien)
    a_l_envers = tri.startswith("ancien") or "croissant" in tri
    gardes.sort(key=lambda p: (p.get("jour", ""), p.get("date", "")), reverse=not a_l_envers)
    lignes, poids = [], 0
    for p in gardes:
        extrait = _extrait_autour(p["texte"], mots) if mots else (
            p["texte"][:900] + (" [...]" if len(p["texte"]) > 900 else ""))
        bloc = "[%s] %s : %s" % (p.get("date") or p.get("jour") or "date inconnue", p["qui"], extrait)
        if poids + len(bloc) > 45000:
            break
        lignes.append(bloc)
        poids += len(bloc)
    jours_vus = sorted({p.get("jour") for p in gardes if p.get("jour")})
    entete = "%d passage(s) sur %d trouve(s), repartis sur %d journee(s) (%s), %s" % (
        len(lignes), total_trouve, len(jours_vus),
        ", ".join(jours_vus[:8]) + (" ..." if len(jours_vus) > 8 else ""),
        "du plus ancien au plus recent" if a_l_envers else "du plus recent au plus ancien")
    if du or au:
        entete += " — periode : du %s au %s" % (du or "le debut", au or "aujourd'hui")
    if approche:
        entete += " — je n'avais pas assez de passages avec TOUS tes mots, j'ai aussi pris les mots proches"
    if total_trouve > len(lignes):
        entete += (" — il en reste %d : demande 'combien' plus grand (jusqu'a 50), une periode, "
                   "ou ouvre une journee entiere avec 'jour'" % (total_trouve - len(lignes)))
    return entete + " :\n\n" + "\n\n".join(lignes)


# =====================================================================
#  v76 : LE JOURNAL DE BORD DES JOURNEES (Documents\Journal_Luciana\AAAA-MM-JJ.md)
#  Ce journal existait deja sur le PC de Fred, mais le programme ne l'ouvrait JAMAIS : c'est
#  absurde, et c'est une des causes de la journee perdue du 01/10/2026. Maintenant il est lu
#  AU LANCEMENT, sans que Fred ait a le demander : la veille + les 2 jours d'avant.
#  On ne l'ECRIT pas, on ne le deplace pas, on ne le modifie pas : on le LIT, c'est tout.
# =====================================================================
JOURNAL_NOM = "Journal_" + NOM_ASSISTANTE          # Journal_Luciana, ou Journal_Luminita
# Chez Fred c'est "Journal_Luciana" ; on accepte aussi l'autre nom et "Journal" tout court,
# pour ne JAMAIS passer a cote d'un journal qui existe vraiment.
JOURNAL_NOMS = (JOURNAL_NOM, "Journal_Luciana", "Journal_Luminita", "Journal")
JOURNAL_JOURS_AU_DEMARRAGE = 3        # la veille + les 2 jours d'avant
_JOURNAL_CACHE = {"jour": "", "texte": "", "dossier": "", "fichiers": []}


def dossier_journal():
    """Le VRAI dossier Documents demande a Windows (francais + OneDrive), jamais devine."""
    bases = []
    if REP.get("documents"):
        bases.append(REP["documents"])
    for b in (HOME, os.path.join(HOME, "OneDrive"), os.path.join(HOME, "OneDrive - Personnel"),
              os.path.join(HOME, "OneDrive - Perso")):
        for n in ("Documents", "Mes documents"):
            bases.append(os.path.join(b, n))
    for base in bases:
        for nom in JOURNAL_NOMS:
            c = os.path.join(base, nom)
            if os.path.isdir(c):
                return c
    return ""


def _fichiers_journal():
    """{'AAAA-MM-JJ': chemin} pour chaque fichier AAAA-MM-JJ.md (ou .txt) du journal."""
    d = dossier_journal()
    trouve = {}
    if not d:
        return trouve
    try:
        for nom in os.listdir(d):
            jour = _jour_de(nom)
            if jour and os.path.splitext(nom)[1].lower() in (".md", ".txt", ".markdown"):
                trouve[jour] = os.path.join(d, nom)
    except Exception:
        pass
    return trouve


def _lire_journal_fichier(chemin, maxi=20000):
    try:
        with open(chemin, "r", encoding="utf-8", errors="replace") as f:
            t = f.read(maxi + 1)
    except Exception:
        return ""
    return t[:maxi] + (" [...]" if len(t) > maxi else "")


def _journal_tous_les_jours():
    """Le journal de chaque journee, pour que 'chercher_dans_memoire' le fouille aussi."""
    return {j: _lire_journal_fichier(c, 20000) for j, c in sorted(_fichiers_journal().items())}


def journal_des_jours_precedents(combien=JOURNAL_JOURS_AU_DEMARRAGE, maxi=18000):
    """Le texte donne d'office a Luciana : le journal des journees DEJA PASSEES (la veille et les
    jours d'avant), plus la LISTE de ses carnets de chantier en cours. Rien d'invente : s'il n'y a
    pas de journal, on le dit franchement."""
    fichiers = _fichiers_journal()
    aujourd_hui = time.strftime("%Y-%m-%d")
    passes = sorted((j for j in fichiers if j < aujourd_hui), reverse=True)[:max(1, combien)]
    blocs, total = [], 0
    for j in passes:
        t = _lire_journal_fichier(fichiers[j], maxi)
        if not t.strip():
            continue
        if total + len(t) > maxi:
            t = t[:max(0, maxi - total)] + " [...]"
        blocs.append("--- JOURNAL DU %s ---\n%s" % (j, t.strip()))
        total += len(t)
        if total >= maxi:
            break
    carnet = charger_carnet()
    liste = ("CARNETS DE CHANTIER EN COURS (%d) : %s." % (len(carnet), ", ".join(carnet))) if carnet else \
            "CARNETS DE CHANTIER EN COURS : aucun pour l'instant."
    if not blocs:
        d = dossier_journal()
        manque = ("Le dossier du journal n'existe pas encore sur ce PC (il devrait etre dans "
                  "Documents\\%s)." % JOURNAL_NOM) if not d else \
                 ("Le dossier %s existe, mais il n'y a pas encore de fichier de journee passee "
                  "(un fichier AAAA-MM-JJ.md par jour)." % d)
        return ("[JOURNAL DE BORD (ouvert par le programme au lancement, pas par toi)]\n%s\n%s\n"
                "Ne fais pas semblant d'avoir lu un journal : si Fred te parle d'hier et que tu n'as "
                "rien ici, fouille avec chercher_dans_memoire (periode 'hier') et dis-lui ce que tu "
                "trouves vraiment." % (manque, liste))
    return ("[JOURNAL DE BORD DES JOURNEES PRECEDENTES (ouvert par le programme au lancement, pas par "
            "toi : tu l'as sous les yeux sans avoir rien demande). C'est ce qui s'est VRAIMENT passe ces "
            "jours-la : repars de la, et ne redemande pas a Fred ce qui est ecrit ici.]\n%s\n\n%s" % (
                liste, "\n\n".join(blocs)))


def journal_du_jour_en_cache():
    """Le journal est lu UNE fois par jour : le texte donne au cerveau ne change pas en cours de
    journee, donc le cache du debut de conversation n'est jamais casse (ca coute 0)."""
    jour = time.strftime("%Y-%m-%d")
    if _JOURNAL_CACHE.get("jour") != jour:
        _JOURNAL_CACHE["jour"] = jour
        _JOURNAL_CACHE["dossier"] = dossier_journal()
        _JOURNAL_CACHE["fichiers"] = sorted(_fichiers_journal())
        _JOURNAL_CACHE["texte"] = journal_des_jours_precedents()
    return _JOURNAL_CACHE["texte"]


# =====================================================================
#  v77 : LE CARNET DE CONSIGNES ET LA LISTE "NE PLUS M'EN PARLER"
#  CE QUI N'ALLAIT PAS (constate le 01/10/2026, pas devine) : Luciana avait DEUX memoires
#  opposees. (1) La conversation du jour, qu'elle a sous les yeux a chaque message, gratuitement,
#  mais c'est un tapis roulant : tout y reste colle, d'ou les REPETITIONS (Fred a demande
#  d'arreter de lui parler de son appel a sa fille, et elle a recommence au message suivant).
#  (2) La memoire longue (souvenirs, carnet) survit a tout, MAIS elle n'existe que si Luciana
#  pense elle-meme a l'ecrire : ca dependait de sa vigilance, donc les choses VRAIMENT
#  importantes (business, projets) passaient a la trappe.
#  CE QUI CHANGE : c'est le PROGRAMME qui garantit le mecanisme, plus sa bonne volonte.
#    - un CARNET DE CONSIGNES, remis sous ses yeux a CHAQUE message (comme le carnet de chantier
#      et le journal de bord le sont deja) ;
#    - une liste NE PLUS M'EN PARLER, remise aussi a chaque message, chaque ligne portant une
#      DATE D'EXPIRATION : passe cette date, la ligne disparait toute seule.
#  REGLE CAPITALE : ces deux fichiers ne sont JAMAIS REECRITS EN ENTIER. On AJOUTE une ligne a la
#  fin (append), c'est tout. C'est exactement ce qui manquait au carnet de chantier : un fichier
#  qu'on reecrit perd les details qui n'ont pas ete recopies (la lecon du prix du PC de Daniela).
#  Une consigne ne disparait que si Fred ou Luciana la retire explicitement — et meme alors, la
#  ligne d'origine reste ecrite dans le fichier : on peut toujours la relire.
# =====================================================================
FICHIER_CONSIGNES = os.path.join(DOSSIER, "consignes.jsonl")
FICHIER_SUJETS_EVITES = os.path.join(DOSSIER, "sujets_a_eviter.jsonl")
# Pour ne pas alourdir (ni faire payer) le contexte : tout reste sur le disque, mais on ne remet
# sous ses yeux que les plus importantes et les plus recentes, dans ces plafonds.
CONSIGNES_DANS_LE_CONTEXTE = 40
CONSIGNES_CARACTERES_MAX = 7000
SUJETS_DANS_LE_CONTEXTE = 25
SUJETS_CARACTERES_MAX = 2500
JOURS_PAR_DEFAUT_SUJET = 30           # "ne m'en parle plus" sans duree dite = un mois
DATE_SANS_LIMITE = "2999-12-31"       # "pour toujours" : une date qui n'arrive jamais
_verrou_consignes = threading.RLock()


def _ajouter_ligne_jsonl(chemin, enregistrement):
    """AJOUTE une ligne a la fin du fichier. Le fichier n'est JAMAIS relu-puis-reecrit : rien ne
    peut disparaitre par accident, meme si le PC s'eteint au mauvais moment."""
    with _verrou_consignes:
        with open(chemin, "a", encoding="utf-8") as f:
            f.write(json.dumps(enregistrement, ensure_ascii=False) + "\n")
            f.flush()
            os.fsync(f.fileno())
    return enregistrement


def _lire_lignes_jsonl(chemin):
    """Toutes les lignes du fichier, dans l'ordre ou elles ont ete ecrites. Une ligne abimee est
    sautee : elle ne fait jamais perdre les autres."""
    lignes = []
    try:
        with open(chemin, "r", encoding="utf-8", errors="replace") as f:
            for brut in f:
                brut = brut.strip()
                if not brut:
                    continue
                try:
                    d = json.loads(brut)
                except Exception:
                    continue
                if isinstance(d, dict):
                    lignes.append(d)
    except FileNotFoundError:
        pass
    except Exception:
        pass
    return lignes


def _prochain_numero(chemin):
    """Le prochain numero libre. Un numero n'est JAMAIS reutilise, meme apres un retrait : comme
    ca, quand Fred dit 'retire la consigne 7', il n'y a aucune confusion possible."""
    n = 0
    for d in _lire_lignes_jsonl(chemin):
        try:
            n = max(n, int(d.get("numero") or 0))
        except Exception:
            pass
    return n + 1


def _jj_mm(horodatage):
    j = _jour_de(horodatage)
    return "%s/%s" % (j[8:10], j[5:7]) if j else "?"


def _date_dans(jours):
    """La date dans 'jours' jours, au format AAAA-MM-JJ."""
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + int(jours) * 86400))


def _duree_en_jours(x):
    """'3 jours', 'une semaine', 'un mois', 'pour toujours', 'aujourd'hui'... -> un nombre de
    jours. -1 = sans limite de temps. None = je n'ai pas compris (on prendra le defaut)."""
    t = _sans_accents(str(x or "")).strip()
    if not t:
        return None
    if any(m in t for m in ("toujours", "definitif", "sans limite", "indefini", "plus jamais")):
        return -1
    if "aujourd" in t or "ce soir" in t or "la journee" in t or "heure" in t:
        return 0
    if "demain" in t:
        return 1
    m = re.search(r"(\d+)", t)
    n = int(m.group(1)) if m else 1
    if not m:   # "deux semaines", "trois jours"... : Fred parle, il ne tape pas des chiffres
        for mot, combien in (("deux", 2), ("trois", 3), ("quatre", 4), ("cinq", 5), ("six", 6),
                             ("sept", 7), ("huit", 8), ("neuf", 9), ("dix", 10), ("quinze", 15)):
            if mot in t:
                n = combien
                break
    if "semaine" in t:
        return n * 7
    if "mois" in t:
        return n * 30
    if "an" in t:
        return n * 365
    if "jour" in t:
        return n
    return n if m else None


def _date_en_clair(jusqu_au):
    j = str(jusqu_au or "")
    if not j or j >= DATE_SANS_LIMITE:
        return "sans limite de temps"
    return "jusqu'au %s" % _jj_mm(j)


# ---------- le carnet de consignes ----------
def consignes_actives():
    """Rejoue le fichier ligne par ligne (ajout, correction, retrait) et rend les consignes encore
    valables, de la plus ancienne a la plus recente. Rien n'est efface du fichier : on se contente
    de tenir compte de ce qui a ete ecrit apres."""
    vivantes = {}
    for d in _lire_lignes_jsonl(FICHIER_CONSIGNES):
        try:
            num = int(d.get("numero") or 0)
        except Exception:
            num = 0
        if not num:
            continue
        action = _sans_accents(str(d.get("action") or "ajouter")).strip()
        if action.startswith("oubli") or action.startswith("retir") or action.startswith("suppr"):
            vivantes.pop(num, None)
            continue
        texte = str(d.get("texte") or "").strip()
        if not texte:
            continue
        ancienne = vivantes.get(num) or {}
        vivantes[num] = {
            "numero": num,
            "texte": texte,
            "importance": str(d.get("importance") or ancienne.get("importance") or "normale"),
            "date": ancienne.get("date") or str(d.get("date") or ""),
            "corrigee": str(d.get("date") or "") if action.startswith("corrig") else ancienne.get("corrigee", ""),
        }
    return [vivantes[n] for n in sorted(vivantes)]


def _est_capitale(c):
    return _sans_accents(str(c.get("importance") or "")).startswith("capital")


def _lignes_qui_tiennent(lignes, maxi):
    """Garde les DERNIERES lignes qui tiennent dans 'maxi' caracteres (donc les plus recentes),
    sans jamais rendre une liste vide quand il y a au moins une ligne."""
    gardees, poids = [], 0
    for ligne in reversed(lignes):
        if gardees and poids + len(ligne) > maxi:
            break
        gardees.append(ligne)
        poids += len(ligne)
    gardees.reverse()
    return gardees


def texte_consignes():
    """Le texte remis sous ses yeux a CHAQUE message. Vide s'il n'y a aucune consigne."""
    actives = consignes_actives()
    if not actives:
        return ""
    # Les consignes marquees IMPORTANTES ne sortent JAMAIS du contexte ; on complete ensuite avec
    # les plus recentes, jusqu'aux plafonds. Tout reste sur le disque de toute facon.
    capitales = [c for c in actives if _est_capitale(c)]
    autres = [c for c in actives if not _est_capitale(c)]
    gardees, poids = [], 0
    for c in capitales[-CONSIGNES_DANS_LE_CONTEXTE:]:
        gardees.append(c)
        poids += len(c["texte"]) + 40
    for c in reversed(autres):
        if len(gardees) >= CONSIGNES_DANS_LE_CONTEXTE:
            break
        if gardees and poids + len(c["texte"]) + 40 > CONSIGNES_CARACTERES_MAX:
            break
        gardees.append(c)
        poids += len(c["texte"]) + 40
    gardees.sort(key=lambda c: c["numero"])
    lignes = ["- n%d (note le %s%s)%s : %s" % (
        c["numero"], _jj_mm(c.get("date")),
        ", corrigee le %s" % _jj_mm(c["corrigee"]) if c.get("corrigee") else "",
        " IMPORTANT" if _est_capitale(c) else "", c["texte"]) for c in gardees]
    reste = len(actives) - len(lignes)
    fin = ("\n(Il y a %d autre(s) consigne(s) gardee(s) en entier sur le disque : ouvre-les avec "
           "l'outil 'consigne', action 'lister'.)" % reste) if reste > 0 else ""
    return ("TON CARNET DE CONSIGNES (%d consigne(s) active(s) ; le programme te le remet sous les yeux "
            "a CHAQUE message, tu n'as rien a aller chercher). Ce sont les consignes que Fred t'a "
            "donnees : elles passent AVANT tes habitudes, et elles restent valables tant qu'il ne te "
            "demande pas de les retirer. Si tu t'apercois que tu allais faire le contraire de l'une "
            "d'elles, arrete-toi et suis la consigne :\n%s%s" % (len(actives), "\n".join(lignes), fin))


def outil_consigne(e):
    """Le carnet de consignes : ajouter, corriger, lister, oublier. Le fichier n'est jamais reecrit."""
    action = _sans_accents(str(e.get("action") or "ajouter")).strip()
    texte = str(e.get("texte") or "").strip()
    importance = _sans_accents(str(e.get("importance") or "")).strip()
    importance = "capitale" if importance.startswith("capital") else "normale"
    try:
        numero = int(e.get("numero") or 0)
    except Exception:
        numero = 0
    actives = consignes_actives()

    def _retrouver():
        """Retrouve une consigne par son numero, ou a defaut par un bout de son texte."""
        if numero:
            for c in actives:
                if c["numero"] == numero:
                    return c, ""
            return None, ("Je n'ai pas de consigne active n%d. Mes consignes actives : %s." % (
                numero, ", ".join("n%d" % c["numero"] for c in actives) or "aucune"))
        reperes = _sans_accents(str(e.get("repere") or texte))
        if not reperes:
            return None, "Dis-moi quelle consigne (son numero, ou un bout de son texte)."
        trouvees = [c for c in actives if reperes in _sans_accents(c["texte"])]
        if not trouvees:
            return None, ("Aucune consigne active ne parle de '%s'. Mes consignes actives : %s." % (
                e.get("repere") or texte,
                " / ".join("n%d %s" % (c["numero"], c["texte"][:60]) for c in actives) or "aucune"))
        if len(trouvees) > 1:
            return None, ("Plusieurs consignes correspondent : %s. Donne-moi le numero." % ", ".join(
                "n%d (%s)" % (c["numero"], c["texte"][:60]) for c in trouvees))
        return trouvees[0], ""

    if action.startswith("list"):
        total_lignes = len(_lire_lignes_jsonl(FICHIER_CONSIGNES))
        if not actives:
            return ("Mon carnet de consignes est vide pour l'instant (fichier %s). Dis-moi 'retiens "
                    "cette consigne : ...' et je l'y ecris tout de suite." % FICHIER_CONSIGNES)
        corps = "\n".join("- n%d (note le %s%s)%s : %s" % (
            c["numero"], _jj_mm(c.get("date")),
            ", corrigee le %s" % _jj_mm(c["corrigee"]) if c.get("corrigee") else "",
            " [IMPORTANT]" if _est_capitale(c) else "", c["texte"]) for c in actives)
        return ("%d consigne(s) active(s), dans %s (%d ligne(s) ecrites en tout : le fichier ne se "
                "reecrit jamais, il s'ajoute) :\n%s" % (
                    len(actives), FICHIER_CONSIGNES, total_lignes, corps))

    if action.startswith("ajout") or action.startswith("note") or action.startswith("ecri"):
        if not texte:
            return "Dis-moi la consigne a ecrire dans mon carnet."
        deja = [c for c in actives if _sans_accents(c["texte"]) == _sans_accents(texte)]
        if deja:
            return "Cette consigne est deja dans mon carnet (n%d), je ne la mets pas en double." % deja[0]["numero"]
        num = _prochain_numero(FICHIER_CONSIGNES)
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "ajouter", "numero": num,
            "texte": texte[:4000], "importance": importance})
        return ("Consigne n%d ecrite pour de vrai dans %s. Je la relis a CHAQUE message a partir de "
                "maintenant, et elle ne disparaitra que si tu me demandes de la retirer." % (
                    num, FICHIER_CONSIGNES))

    if action.startswith("corrig") or action.startswith("modif"):
        if not texte:
            return "Dis-moi le nouveau texte de la consigne."
        if not numero and not str(e.get("repere") or "").strip():
            # Sans repere, on chercherait le NOUVEAU texte parmi les anciennes : ca ne trouve rien.
            return ("Dis-moi LAQUELLE je corrige : son numero, ou un bout de son ancien texte "
                    "('repere'). Mes consignes actives : %s." % (
                        " / ".join("n%d %s" % (c["numero"], c["texte"][:60]) for c in actives)
                        or "aucune"))
        c, souci = _retrouver()
        if not c:
            return souci
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "corriger", "numero": c["numero"],
            "texte": texte[:4000], "importance": importance if importance == "capitale" else c.get("importance")})
        return ("Consigne n%d corrigee pour de vrai. L'ancien texte reste ecrit dans le fichier (il "
                "n'est jamais efface) : \"%s\"." % (c["numero"], c["texte"][:200]))

    if action.startswith("oubli") or action.startswith("retir") or action.startswith("suppr"):
        c, souci = _retrouver()
        if not c:
            return souci
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "oublier", "numero": c["numero"],
            "texte": c["texte"][:4000]})
        return ("Consigne n%d retiree de mon carnet : je ne l'applique plus. Son texte reste ecrit "
                "dans le fichier, donc on peut toujours la relire : \"%s\"." % (
                    c["numero"], c["texte"][:200]))

    return "Action inconnue '%s'. Actions : ajouter, corriger, lister, oublier." % action


# ---------- la liste "ne plus m'en parler" ----------
def sujets_a_eviter_actifs(aujourd_hui=None):
    """Les sujets encore valables aujourd'hui. Une ligne dont la date d'expiration est passee
    disparait TOUTE SEULE de cette liste (elle reste ecrite dans le fichier)."""
    jour = aujourd_hui or time.strftime("%Y-%m-%d")
    vivants = {}
    for d in _lire_lignes_jsonl(FICHIER_SUJETS_EVITES):
        try:
            num = int(d.get("numero") or 0)
        except Exception:
            num = 0
        if not num:
            continue
        action = _sans_accents(str(d.get("action") or "ajouter")).strip()
        if action.startswith("retir") or action.startswith("oubli") or action.startswith("suppr"):
            vivants.pop(num, None)
            continue
        sujet = str(d.get("sujet") or "").strip()
        if not sujet:
            continue
        vivants[num] = {"numero": num, "sujet": sujet, "date": str(d.get("date") or ""),
                        "jusqu_au": str(d.get("jusqu_au") or DATE_SANS_LIMITE)}
    return [vivants[n] for n in sorted(vivants) if vivants[n]["jusqu_au"] >= jour]


def texte_sujets_a_eviter():
    """Le texte remis sous ses yeux a CHAQUE message. Vide s'il n'y a aucun sujet a eviter."""
    actifs = sujets_a_eviter_actifs()
    if not actifs:
        return ""
    lignes = ["- %s (%s)" % (s["sujet"], _date_en_clair(s.get("jusqu_au"))) for s in actifs]
    lignes = _lignes_qui_tiennent(lignes[-SUJETS_DANS_LE_CONTEXTE:], SUJETS_CARACTERES_MAX)
    return ("NE PLUS LUI EN PARLER (Fred l'a demande expressement ; le programme te le redit a CHAQUE "
            "message). Tu n'abordes JAMAIS ces sujets de toi-meme : pas de question dessus, pas de "
            "'au fait, et...', pas de conseil, pas de retour dessus parce que tu y repenses. Si c'est "
            "FRED qui en parle, la tu reponds normalement, bien sur. Et tu ne lui annonces pas que tu "
            "evites le sujet : tu le laisses simplement de cote :\n%s" % "\n".join(lignes))


def outil_sujet_a_eviter(e):
    """La liste 'ne plus m'en parler' : ajouter (avec une duree facultative), lister, retirer."""
    action = _sans_accents(str(e.get("action") or "ajouter")).strip()
    sujet = str(e.get("sujet") or "").strip()
    actifs = sujets_a_eviter_actifs()

    if action.startswith("list"):
        total = len(_lire_lignes_jsonl(FICHIER_SUJETS_EVITES))
        if not actifs:
            return ("Il n'y a aucun sujet a eviter en ce moment (fichier %s, %d ligne(s) ecrites en "
                    "tout, dont les expirees)." % (FICHIER_SUJETS_EVITES, total))
        corps = "\n".join("- n%d : %s (%s, note le %s)" % (
            s["numero"], s["sujet"], _date_en_clair(s.get("jusqu_au")), _jj_mm(s.get("date")))
            for s in actifs)
        return "%d sujet(s) dont je ne parle plus :\n%s" % (len(actifs), corps)

    if action.startswith("retir") or action.startswith("oubli") or action.startswith("suppr"):
        try:
            numero = int(e.get("numero") or 0)
        except Exception:
            numero = 0
        choisi = None
        if numero:
            choisi = next((s for s in actifs if s["numero"] == numero), None)
        elif sujet:
            repere = _sans_accents(sujet)
            trouves = [s for s in actifs if repere in _sans_accents(s["sujet"])]
            if len(trouves) > 1:
                return "Plusieurs sujets correspondent : %s. Donne-moi le numero." % ", ".join(
                    "n%d (%s)" % (s["numero"], s["sujet"]) for s in trouves)
            choisi = trouves[0] if trouves else None
        if not choisi:
            return ("Je ne trouve pas ce sujet dans ma liste. Ce que j'ai : %s." % (
                " / ".join("n%d %s" % (s["numero"], s["sujet"]) for s in actifs) or "rien"))
        _ajouter_ligne_jsonl(FICHIER_SUJETS_EVITES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "retirer",
            "numero": choisi["numero"], "sujet": choisi["sujet"]})
        return "C'est retire : je peux de nouveau te parler de %s." % choisi["sujet"]

    if action.startswith("ajout") or action.startswith("evit") or action.startswith("note"):
        if not sujet:
            return "Dis-moi de quel sujet je ne dois plus te parler."
        jours = e.get("jours")
        if jours is None or str(jours).strip() == "":
            jours = _duree_en_jours(e.get("duree"))
        else:
            try:
                jours = int(jours)
            except Exception:
                jours = _duree_en_jours(e.get("duree"))
        jusqu_au = _lire_date(e.get("jusqu_au"))
        if not jusqu_au:
            if jours is None:
                jours = JOURS_PAR_DEFAUT_SUJET
            jusqu_au = DATE_SANS_LIMITE if jours < 0 else _date_dans(jours)
        deja = [s for s in actifs if _sans_accents(s["sujet"]) == _sans_accents(sujet)]
        num = deja[0]["numero"] if deja else _prochain_numero(FICHIER_SUJETS_EVITES)
        _ajouter_ligne_jsonl(FICHIER_SUJETS_EVITES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "ajouter", "numero": num,
            "sujet": sujet[:1000], "jusqu_au": jusqu_au})
        return ("C'est note pour de vrai (%s, ligne n%d) : je ne te parle plus de %s, %s. Je ne "
                "relancerai pas le sujet de moi-meme ; si c'est toi qui m'en parles, je te reponds "
                "normalement. Passe cette date, la ligne disparait toute seule." % (
                    FICHIER_SUJETS_EVITES, num, sujet, _date_en_clair(jusqu_au)))

    return "Action inconnue '%s'. Actions : ajouter, lister, retirer." % action


