_client_ds = {"cle": None, "client": None}


def client_de(cerveau):
    """Rend le client a utiliser pour ce cerveau. Claude -> le client d'avant (inchange)."""
    if fournisseur_de(cerveau) != "deepseek":
        return client
    cle = lire_cle_deepseek()
    if not cle:
        return None
    if _client_ds["cle"] != cle:
        _client_ds["client"] = _client_deepseek()
        _client_ds["cle"] = cle
    return _client_ds["client"]


def definir_cle_deepseek(nouvelle):
    """Enregistre la cle DeepSeek dans ~/Luciana/cle_deepseek.txt."""
    nouvelle = (nouvelle or "").strip()
    if not nouvelle.startswith("sk-"):
        return False, "Cette cle ne ressemble pas a une cle API (elle commence par sk-)."
    try:
        with open(FICHIER_CLE_DEEPSEEK, "w", encoding="utf-8") as f:
            f.write(nouvelle)
        _client_ds["cle"] = None  # on refabriquera le client avec la nouvelle cle
        _client_ds["client"] = None
        return True, ""
    except Exception as e:
        return False, str(e)


def definir_cle(nouvelle):
    """Enregistre la cle collee depuis la fenetre de Luciana.
    v75 : une cle Claude commence par 'sk-ant-' -> elle va dans cle_api.txt (comme avant).
    Une AUTRE cle en 'sk-' est prise pour une cle DeepSeek -> elle va dans cle_deepseek.txt.
    Rend (ok, erreur, ou_est_allee_la_cle)."""
    global CLE, client
    nouvelle = (nouvelle or "").strip()
    if not nouvelle.startswith("sk-"):
        return False, "Cette cle ne ressemble pas a une cle API (celle de Claude commence par sk-ant-, celle de DeepSeek par sk-).", ""
    if not nouvelle.startswith("sk-ant-"):
        ok, err = definir_cle_deepseek(nouvelle)
        return ok, err, ("deepseek" if ok else "")
    try:
        with open(FICHIER_CLE, "w", encoding="utf-8") as f:
            f.write(nouvelle)
        CLE = nouvelle
        client = anthropic.Anthropic(api_key=nouvelle)
        return True, "", "claude"
    except Exception as e:
        return False, str(e), ""


# ---------- v76 : LA CLE, MONTREE SANS ETRE MONTREE, ET VERIFIEE POUR DE VRAI ----------
def cle_masquee(cle=None):
    """La cle telle qu'on l'affiche a l'ecran : sk-ant-••••••••3f2a. Le milieu ne sort jamais."""
    c = (cle if cle is not None else (lire_cle() or "")).strip()
    if not c:
        return ""
    if len(c) <= 12:
        return "•" * 8
    return c[:7] + "•" * 8 + c[-4:]


# Le modele le MOINS CHER de la table des cerveaux (c'est lui qui sert au test de la cle).
def _modele_le_moins_cher():
    claude = [(v["prix"][0] + v["prix"][1], v["modele"]) for v in CERVEAUX.values()
              if v.get("fournisseur") == "anthropic"]
    return min(claude)[1] if claude else "claude-haiku-4-5"


def _cle_en_clair(ex):
    """Traduit n'importe quelle panne de l'API en une phrase que Fred comprend. JAMAIS un code
    technique : il n'est pas technicien, et un code ne lui dit rien."""
    t = (str(ex) + " " + type(ex).__name__).lower()
    if any(m in t for m in ("authentication", "invalid x-api-key", "invalid api key", "401",
                            "unauthorized", "permission_error", "403")):
        return ("Ta cle est REFUSEE par le service : elle est fausse, expiree, ou elle a ete revoquee. "
                "Il faut en recoller une neuve (bouton 'Remplacer la cle').")
    if any(m in t for m in ("credit balance", "insufficient", "402", "billing", "payment",
                            "quota", "exceeded your")):
        return ("Ta cle est bonne, mais il n'y a PLUS D'ARGENT sur le compte (ou le plafond est "
                "atteint). Recharge le compte et je repars aussitot.")
    if any(m in t for m in ("rate limit", "429", "too many")):
        return ("Ta cle marche. Le service te demande juste d'attendre un petit moment : trop de "
                "demandes d'un coup. Reessaie dans une minute.")
    if any(m in t for m in ("connection", "timeout", "timed out", "ssl", "getaddrinfo", "network",
                            "unreachable", "dns", "proxy", "overloaded", "500", "502", "503", "504")):
        return ("Je N'AI PAS PU JOINDRE le service : ca vient de la connexion internet ou du service "
                "lui-meme, pas de ta cle. Reessaie dans un moment.")
    return ("Je n'ai pas pu verifier ta cle : le service a repondu quelque chose que je ne sais pas "
            "t'expliquer simplement. Reessaie dans un instant, et si ca recommence, remplace la cle.")


def verifier_cle_api():
    """Un VRAI petit appel : 16 jetons au maximum, sur le modele le moins cher. Rend une phrase
    en francais clair, jamais un code technique."""
    c = lire_cle()
    if not c:
        return {"ok": False, "msg": "Il n'y a aucune cle Claude enregistree pour l'instant. Colle-la ici."}
    modele = _modele_le_moins_cher()
    try:
        cli = anthropic.Anthropic(api_key=c)
        cli.messages.create(model=modele, max_tokens=16,
                            messages=[{"role": "user", "content": "Reponds juste : ok"}])
        return {"ok": True, "msg": "Ta cle MARCHE : le service a repondu. (Test minuscule : 16 jetons "
                                   "au maximum, sur le modele le moins cher, ca ne coute presque rien.)"}
    except Exception as ex:
        return {"ok": False, "msg": _cle_en_clair(ex)}


