def demarrer_serveur():
    # On ecoute sur 0.0.0.0 pour pouvoir aussi ouvrir Luciana depuis le telephone
    # ou l'iPad, sur le meme WiFi que le PC.
    for port in PORTS:
        try:
            srv = ThreadingHTTPServer(("0.0.0.0", port), Handler)
            srv.daemon_threads = True  # une demande lente ne bloque jamais les autres
            return srv, port
        except OSError:
            continue
    return None, None


def _ip_locale():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return None


def _ouvrir_le_journal_au_demarrage():
    """v76 : AU LANCEMENT, le programme ouvre lui-meme le journal des journees precedentes et la
    liste des carnets en cours, et le met sous les yeux de Luciana. Fred n'a rien a demander.
    On DIT a l'ecran ce qui a vraiment ete lu : jamais une fausse reussite."""
    try:
        journal_du_jour_en_cache()
        d = _JOURNAL_CACHE.get("dossier") or ""
        jours = _JOURNAL_CACHE.get("fichiers") or []
        passes = [j for j in jours if j < time.strftime("%Y-%m-%d")][-JOURNAL_JOURS_AU_DEMARRAGE:]
        carnet = charger_carnet()
        if passes:
            print("  Journal de bord ouvert : %s  (dossier %s)" % (", ".join(reversed(passes)), d))
        elif d:
            print("  Journal de bord : dossier trouve (%s) mais aucune journee passee dedans." % d)
        else:
            print("  Journal de bord : pas de dossier Documents\\%s sur ce PC (rien a ouvrir)." % JOURNAL_NOM)
        print("  Carnets de chantier en cours : %s" % (", ".join(carnet) if carnet else "aucun"))
    except Exception as ex:
        print("  (journal de bord : %s)" % str(ex)[:200])


def _afficher_consignes_au_demarrage():
    """v77 : au lancement, Fred VOIT dans la fenetre noire ce que Luciana a vraiment sous les yeux :
    ses consignes actives et les sujets dont il a demande qu'on ne lui parle plus. S'il n'y a rien,
    on le dit : jamais une fausse reussite."""
    try:
        actives = consignes_actives()
        if actives:
            print("  Consignes actives (%d) — relues a chaque message :" % len(actives))
            for c in actives[-12:]:
                print("    - n%d%s : %s" % (c["numero"], " [IMPORTANT]" if _est_capitale(c) else "",
                                            str(c["texte"])[:140]))
            if len(actives) > 12:
                print("    (... et %d autre(s), toutes gardees dans %s)" % (
                    len(actives) - 12, FICHIER_CONSIGNES))
        else:
            print("  Consignes actives : aucune pour l'instant (fichier %s)." % FICHIER_CONSIGNES)
    except Exception as ex:
        print("  (carnet de consignes : %s)" % str(ex)[:200])
    try:
        sujets = sujets_a_eviter_actifs()
        if sujets:
            print("  Sujets dont je ne parle plus (%d) :" % len(sujets))
            for s in sujets[:12]:
                print("    - %s  (%s)" % (str(s["sujet"])[:120], _date_en_clair(s.get("jusqu_au"))))
            if len(sujets) > 12:
                print("    (... et %d autre(s).)" % (len(sujets) - 12))
        else:
            print("  Sujets a eviter : aucun pour l'instant.")
    except Exception as ex:
        print("  (sujets a eviter : %s)" % str(ex)[:200])


def _afficher_travaux_au_demarrage():
    """v78 : au lancement, Fred VOIT dans la fenetre noire ce qui tournait encore et, surtout, ce
    qu'il a VALIDE et qui n'est pas encore revenu sur le PC. Rien ne se perd a l'arret du programme."""
    print("\n  --- TRAVAUX ET VALIDATIONS (v81) ---")
    try:
        en_cours = travaux_en_cours()
        if en_cours:
            # Un travail "en cours" trouve AU LANCEMENT ne tourne plus : il tournait dans
            # l'ancienne fenetre, qui est fermee. On le dit, et on referme la fiche pour ne pas
            # afficher un faux "en cours" a vie (et ne pas reveiller le veilleur pour rien).
            for t in en_cours:
                print("  INTERROMPU par l'arret du programme (il ne tourne plus) : %s (lance a %s)"
                      % (t.get("libelle"), t.get("depuis")))
                travail_fini(t.get("id"))
                # v81 : et on l'ecrit dans le journal permanent des chantiers, pour que la ligne
                # d'etat a l'ecran le dise aussi, et ne laisse pas croire qu'il s'est bien termine.
                if str(t.get("genre") or "") == "chantier":
                    noter_etat_chantier(t.get("id"), "echec", libelle=t.get("libelle"),
                                        raison="interrompu par l'arret du programme : il n'a rien rendu")
            print("  (Si tu veux ces travaux, il faut les relancer : je ne fais pas semblant.)")
        else:
            print("  Aucun travail long en cours.")
    except Exception as ex:
        print("  (travaux en cours : %s)" % str(ex)[:200])
    try:
        a_recuperer = chantiers_a_recuperer()
        if a_recuperer:
            for x in a_recuperer:
                print("  A RECUPERER : « %s » (depot %s) -> %s"
                      % (x.get("titre"), x.get("depot") or "?", x.get("dossier") or "dossier local inconnu"))
        else:
            print("  Rien a recuperer : tout ce que tu as valide est deja revenu sur le PC.")
    except Exception as ex:
        print("  (a recuperer : %s)" % str(ex)[:200])
    # v81 : la ligne d'etat des chantiers SURVIT a l'arret du programme. Au lancement, Fred la voit
    # dans la fenetre noire, exactement comme elle est ecrite sur le disque.
    try:
        recents = etat_chantiers(6)
        if recents:
            print("  Etat des derniers chantiers (garde sur le disque, %s) :" % FICHIER_ETAT_CHANTIERS)
            for x in recents:
                print("    - %s : %s%s [%s]" % (x.get("libelle") or "(chantier)",
                                                x.get("phrase") or x.get("etat") or "?",
                                                (" — %s" % x.get("raison")) if x.get("raison") else "",
                                                x.get("fini_a") or x.get("commence_a") or "?"))
        else:
            print("  Aucun chantier dans le journal d'etat (c'est normal si tu n'en as pas lance).")
    except Exception as ex:
        print("  (etat des chantiers : %s)" % str(ex)[:200])
    # v81 : et ce qui ATTEND d'etre annonce. Un rapport pret ne peut plus etre invisible : il est
    # dit ici au lancement, et affiche en permanence dans la page tant que Fred ne l'a pas traite.
    try:
        attente = rapports_en_attente()
        if attente:
            # v82 : ce ne sont plus des rapports qui "vont tomber", ce sont des PASTILLES qui
            # attendent le clic de Fred. On le dit comme c'est.
            print("  %d compte(s)-rendu PRET(S) : une pastille t'attend dans la page pour chacun "
                  "(rien ne partira tout seul) :" % len(attente))
            for x in attente:
                print("    - %s (pret depuis %d min)%s" % (x.get("titre"), x.get("minutes") or 0,
                                                           " [A VALIDER]" if x.get("a_valider") else ""))
        else:
            print("  Aucun compte-rendu en attente.")
    except Exception as ex:
        print("  (comptes-rendus en attente : %s)" % str(ex)[:200])
    # v82 : et la pastille du point de communication / de l'audit. Elle n'interrompt plus jamais
    # Fred : elle attend son clic. Dite ici pour qu'il la voie des le lancement.
    try:
        comm = pastille_communication()
        if comm:
            print("  PASTILLE : %s — en attente depuis %s. Elle ne te coupera pas : clique dessus "
                  "quand tu veux le compte-rendu."
                  % (comm.get("titre"), ("%d min" % comm["minutes"]) if comm.get("minutes", -1) >= 0 else "un moment"))
        else:
            print("  Aucun point de communication en attente.")
    except Exception as ex:
        print("  (point de communication en attente : %s)" % str(ex)[:200])


def _verifier_bibliotheques():
    """v76 : la lecon du 01/10. Sur le PC de la cliente, PILLOW manquait : 'import pyautogui'
    plantait (ModuleNotFoundError: PIL) et l'assistante se retrouvait sans souris ni capture
    d'ecran. On le DIT tout de suite, avec la ligne exacte a taper."""
    manque = []
    for nom_import, nom_pip in (("anthropic", "anthropic"), ("requests", "requests"), ("PIL", "PILLOW")):
        try:
            __import__(nom_import)
        except ImportError:
            manque.append(nom_pip)
    if manque:
        print("\n  ATTENTION : il manque %s sur ce PC." % " et ".join(manque))
        print("  Tape ceci dans la fenetre noire, puis relance Luciana :")
        print("      pip install anthropic edge-tts requests PILLOW")
        if "PILLOW" in manque:
            print("  (Sans PILLOW, je n'ai ni souris ni capture d'ecran : je ne peux plus te guider.)\n")


def main():
    sauvegarde_du_jour()  # copie du jour de la memoire, des souvenirs, du carnet et des comptes
    _verifier_bibliotheques()           # v76 : la liste d'installation complete, dite en clair
    _ouvrir_le_journal_au_demarrage()   # v76 : le journal des jours d'avant, donne d'office
    _afficher_consignes_au_demarrage()  # v77 : les consignes actives et les sujets a eviter
    _afficher_travaux_au_demarrage()    # v78 : ce qui tourne encore, et ce qui attend d'etre recupere
    threading.Thread(target=_boucle_coucou, daemon=True).start()  # garde le cache au chaud
    threading.Thread(target=_boucle_sauvegarde_auto, daemon=True).start()  # sauvegarde verifiee chaque jour
    threading.Thread(target=_boucle_veilleur, daemon=True).start()  # veilleur de mails + alertes en attente
    threading.Thread(target=_boucle_suivi_correspondance, daemon=True).start()  # v76 : suivi (0 token)
    threading.Thread(target=_boucle_veilleur_travaux, daemon=True).start()  # v78 : plus jamais de silence
    # Prepare la belle voix gratuite (Microsoft) en arriere-plan, sans bloquer.
    if not EDGE_OK:
        print("  (Je prepare ma belle voix, ca se fait tout seul une seule fois...)")
        threading.Thread(target=_installer_edge, daemon=True).start()
    srv, port = demarrer_serveur()
    _PORT_ACTUEL[0] = port
    if srv is None:
        print("  Impossible d'ouvrir un port. Ferme les autres fenetres Luciana et relance.")
        return
    url = "http://127.0.0.1:%d" % port
    ip = _ip_locale()
    print("\n  Luciana est reveillee.  <3")
    print("  Sur ce PC : " + url + "   (elle s'ouvre toute seule)")
    if ip:
        print("  Sur ton telephone ou iPad (meme WiFi) : http://%s:%d" % (ip, port))
        print("  (Sur le telephone, tu ecris et elle te repond a voix haute.)")
    print("")
    print("  +---------------------------------------------------------+")
    print("  |  CODE D'ACCES pour le telephone : %-6s                |" % CODE_ACCES)
    print("  |  (a taper une seule fois sur le tel ; le PC n'en a pas  |")
    print("  |   besoin. Personne ne peut me commander sans ce code.)  |")
    print("  +---------------------------------------------------------+")
    print("")
    print("  (Sur le PC, utilise Google Chrome pour que le micro marche.)")
    print("  Pour l'arreter : ferme cette fenetre.\n")
    threading.Timer(1.0, lambda: webbrowser.open(url)).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\n  A bientot. Luciana se met en veille.\n")


